import{z as l,x as r,o as e,c as s,q as t,j as A,D as E,d as o,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"接触孔与通孔图形化","description":"","frontmatter":{"title":"接触孔与通孔图形化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/contact-hole-patterning.md","filePath":"litho/contact-hole-patterning.md","lastUpdated":1791063341000}'),p={name:"litho/contact-hole-patterning.md"};function h(D,a,d,c,_,m){const B=r("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="接触孔与通孔图形化" tabindex="-1">接触孔与通孔图形化 <a class="header-anchor" href="#接触孔与通孔图形化" aria-label="Permalink to &quot;接触孔与通孔图形化&quot;">​</a></h1><div class="epigraph"><p>线空是一维节距问题；孔是二维通带里的暗点。对比更差、随机更毒、刻蚀更深宽比，三件事叠在同一类图形上。</p><footer>—— 对照 Mack 对接触孔空中像与工艺窗的讨论，以及 EUV 孔阵列随机缺失的公开论述</footer></div><p><a href="/litho/etch-loading-ar">上一课</a>说明深孔先付 ARDE 和过刻。缺口是：孔在成像端本来就比线空难——两个方向都要进瞳，NILS 更低，EUV 上还先死在泊松缺孔。本课钉接触孔与通孔图形化，对照线栅。后道各层并不共用这一套波长，留给<a href="/litho/beol-wavelength-mix">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>密线可以靠两束干涉在瞳内站住；接触孔的频谱是二维的，要同时过 \\(x\\) 与 \\(y\\) 的截止。同样 \\(k_1\\) 叙事下，孔的空中像对比和边缘陡度通常差一截，Bossung 先关。Mack 把孔写成与孤立线、密线并列的图形族：层的工艺窗是交集，孔常常是短板。</p><p><span class="marginnote">术语翻译：Bossung 图是一族「孔径随焦面上下移动怎么变」的曲线，量焦深常用它。说孔的 Bossung 先关，意思是焦点还没偏多少，孔就先掉出窗口——孔对离焦比线敏感得多。</span></p><p>EUV 把短板从「对比不够」加成「计数不够」。小孔体积里光子少，缺失孔随剂量陡变，见<a href="/litho/euv-stochastics">随机效应</a>。DUV 多重可以用两次线空拼孔，或用负显影，但套刻和循环进来。缺口是：孔不是「短一点的线」，不能把线栅 OPC 配方直接贴到孔阵列上。</p><h3 id="孔的焦深更瘦" tabindex="-1">孔的焦深更瘦 <a class="header-anchor" href="#孔的焦深更瘦" aria-label="Permalink to &quot;孔的焦深更瘦&quot;">​</a></h3><p>离焦时高频先死；孔更依赖高频，轴向窗更窄。浸没与 High-NA 再削 \\(\\mathrm{NA}^2\\)。设计上放宽孔、加冗余通孔，是在买统计与窗，不是承认光学公式失效。</p><p><span class="marginnote">通孔（via）与接触孔（contact）成像同类、衬底不同：一个进金属间介质，一个进前层介质/硅化物。ARDE 与选择比要按膜堆重标，光学对比可以共用讨论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>照明：常规圆照明对孔往往比强偶极更稳，因为孔要各向同性；十字或弱四极是常见折中，强线栅偶极会把孔拉成长圆。掩模：衰减相移对孔是产线默认之一，暗区漏光加相位抬对比。OPC：孔要修的是直径、长短轴和邻近孔的合并风险，SRAF 更易印出旁瓣，MRC 要按住。</p><p>EUV 单次孔：剂量、胶吸收和 SMO 先服务缺陷密度，再服务平均 CD。随机感知的目标函数把缺孔写进损失，而不是只盯名义直径。电学冗余通孔把泊松尾从良率里挪走一部分。刻蚀端按上一课：过刻以最慢孔为准，线层不要用同一过刻百分比。</p><p><span class="marginnote">直觉类比：冗余通孔像给关键连接买双保险——两个并联孔里有一个泊松缺失，另一个还通，电流照走。花的代价是面积与寄生参数，换回的是把缺孔风险从良率账上挪走一部分。</span></p>',14)),(e(),A(i,null,{default:E(()=>[n(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20LS%5B%22%E7%BA%BF%E7%A9%BA%3A%20%E4%B8%80%E7%BB%B4%E4%B8%A4%E6%9D%9F%22%5D%20--%3E%20WIN%5B%22%E5%B1%82%E7%AA%97%E5%8F%A3%20%3D%20%E4%BA%A4%E9%9B%86%22%5D%0A%20%20HOLE%5B%22%E5%AD%94%3A%20%E4%BA%8C%E7%BB%B4%E9%80%9A%E5%B8%A6%22%5D%20--%3E%20NILS%5B%22%E6%9B%B4%E4%BD%8E%20NILS%20%2F%20%E6%9B%B4%E7%98%A6%E7%84%A6%E6%B7%B1%22%5D%0A%20%20STO%5B%22EUV%20%E5%85%89%E5%AD%90%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20MISS%5B%22%E7%BC%BA%E5%A4%B1%E5%AD%94%22%5D%0A%20%20AR%5B%22%E9%AB%98%20AR%20%E8%BD%AC%E5%8D%B0%22%5D%20--%3E%20ARDE%5B%22%E8%BF%87%E5%88%BB%E4%BB%A5%E5%AD%94%E4%B8%BA%E5%87%86%22%5D%0A%20%20NILS%20--%3E%20WIN%0A%20%20MISS%20--%3E%20WIN%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="阵列与孤立孔不是同一条-bossung" tabindex="-1">阵列与孤立孔不是同一条 Bossung <a class="header-anchor" href="#阵列与孤立孔不是同一条-bossung" aria-label="Permalink to &quot;阵列与孤立孔不是同一条 Bossung&quot;">​</a></h3><p>密孔阵列有光学邻近，也有刻蚀微负荷；孤立孔对比和负荷都不同。OPC 和食谱必须分族。把阵列 CD 合格写成「孔层已通」，孤立孔或不规则二维通孔仍可能桥或封。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成像：孔的暗区靠周围亮区的衍射级在中心相消；级一少，中心抬起来，阈值胶切出的孔变小或封死。这与线空「暗线靠两级干涉」同构，但自由度少一维。Mack 用 NILS 在孔边缘取值，而不是只用一维对比度公式。</p><p>随机：平均空中像可以「刚开孔」，泊松使一部分孔落在阈值下。缺陷率对剂量近似指数，产线表现为剂量一降缺孔爆炸。刻蚀：孔 AR 高，ARDE 让底部聚合物和钝化更易封口，过刻与高选择比是在补成像留下的深坑，不是补 \\(k_1\\)。</p><p><span class="marginnote">数字实例：泊松涨落的相对幅度约 \\(1/\\sqrt{N}\\)。若一个小孔平均只收到 \\(N=50\\) 个光子，涨落约 14%；剂量减半到 \\(N=25\\)，涨落升到 20%，落到阈值下的孔按指数增多——这就是「剂量一降缺孔爆炸」的来源。</span></p>',6)),(e(),A(i,null,{default:E(()=>[n(B,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E5%AD%94%E9%A2%91%E8%B0%B1%E6%98%AF%E4%BA%8C%E7%BB%B4%3A%20x%E3%80%81y%20%E9%83%BD%E8%A6%81%E8%BF%87%E6%88%AA%E6%AD%A2%22%5D%20--%3E%20FEW%5B%22%E8%BF%9B%E7%9E%B3%E8%A1%8D%E5%B0%84%E7%BA%A7%E6%9B%B4%E5%B0%91%22%5D%0A%20%20FEW%20--%3E%20CANCEL%5B%22%E4%B8%AD%E5%BF%83%E7%9B%B8%E6%B6%88%E4%B8%8D%E5%BD%BB%E5%BA%95%22%5D%0A%20%20CANCEL%20--%3E%20SMALL%5B%22%E9%98%88%E5%80%BC%E5%88%87%E5%87%BA%E7%9A%84%E5%AD%94%E5%8F%98%E5%B0%8F%20%2F%20%E5%B0%81%E6%AD%BB%22%5D%0A%20%20FEW%20--%3E%20DEFOC%5B%22%E7%A6%BB%E7%84%A6%3A%20%E9%AB%98%E9%A2%91%E5%85%88%E6%AD%BB%22%5D%20--%3E%20THIN%5B%22%E8%BD%B4%E5%90%91%E7%AA%97%E6%9B%B4%E7%98%A6%22%5D%0A%20%20PH%5B%22%E5%B0%8F%E5%AD%94%E5%85%89%E5%AD%90%E6%95%B0%E5%B0%91%22%5D%20--%3E%20POI%5B%22%E6%B3%8A%E6%9D%BE%E6%B6%A8%E8%90%BD%3A%20%E9%83%A8%E5%88%86%E5%AD%94%E6%95%B4%E4%BD%93%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20SMALL%20--%3E%20WIN2%5B%22%E5%AD%94%E5%85%88%E5%85%B3%E7%AA%97%22%5D%0A%20%20POI%20--%3E%20WIN2%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">缺孔看起来像掩模缺陷或颗粒，统计上随剂量和孔面积变。分析要把重复性掩模缺陷与泊松尾拆开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把某一代 EUV 孔的未公开缺陷密度表填进本课。不要说「孔必须 EUV」——后道松节距通孔仍用 ArF 甚至 KrF。本课不重写 LELE 染色，只承认两次线空拼孔是 DUV 的一条路。也不把金属氧化物胶写成孔层唯一解；胶三角在<a href="/litho/euv-resist">EUV 胶</a>。</p><p>下一课把后道多层写成波长分层：不是每一层通孔都配最先进的孔工艺。</p><p><span class="marginnote">出处：Mack, <em>Fundamental Principles of Optical Lithography</em> 中对接触孔与图形族窗口的讨论；EUV 孔随机缺失的公开综述与产线表述。不编造某厂孔缺陷 ppm。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>孔是二维图形，NILS 与焦深通常差于同类 \\(k_1\\) 的线空。</li><li>层窗口是孔与线的交集；孔常先关窗。</li><li>EUV 小孔先付光子统计（缺失孔），再付 ARDE。</li><li>照明与 OPC 不能从线栅配方直接拷贝。</li><li>后道波长分层下一课。</li><li>出处：Mack；EUV 孔随机效应公开论述。</li></ul>',7))])}const f=l(p,[["render",h]]);export{S as __pageData,f as default};
